import { useActionMutation, useActionQuery } from "../use-action.js";
export function useResourceVersions(params, options) {
    return useActionQuery("list-resource-versions", params, {
        enabled: options?.enabled ?? Boolean(params.resourceType && params.resourceId),
    });
}
export function useResourceHistory(params, options) {
    return useActionQuery("list-resource-history", params, {
        enabled: options?.enabled ?? Boolean(params.resourceType && params.resourceId),
    });
}
export function useResourceVersion(params, options) {
    const enabled = options?.enabled ??
        Boolean(params.id ||
            (params.resourceType && params.resourceId && params.versionNumber));
    return useActionQuery("get-resource-version", params, { enabled });
}
export function useCreateResourceVersion() {
    return useActionMutation("create-resource-version");
}
export function useRestoreResourceVersion() {
    return useActionMutation("restore-resource-version");
}
